const CHAT_KEYS = Object.freeze({
  case: "date_simulator.case",
  phase: "date_simulator.phase",
  trackerVersion: "date_simulator.tracker_version",
  scene: "date_simulator.scene_v2",
  arc: "date_simulator.arc_v2",
  legacyArc: "date_simulator.arc_v1",
  revision: "date_simulator.tracker_revision",
});

const INACTIVE_CASE = "INACTIVE: The previous case ended. Await a new case capsule.";
const VERSION_PATTERN = /<date_simulator_version>\s*1\.(?:4|5)(?:\.\d+)?\s*<\/date_simulator_version>/i;
const V15_VERSION_PATTERN = /<date_simulator_version>\s*1\.5(?:\.\d+)?\s*<\/date_simulator_version>/i;
const CASE_PATTERN = /<!--DATE_SIM_CASE\s*([\s\S]*?)\s*END_DATE_SIM_CASE-->/gi;
const LEGACY_SCENE_PATTERN = /<!--DATE_SIM_SCENE\s*([\s\S]*?)\s*END_DATE_SIM_SCENE-->/gi;
const RESET_PATTERN = /<!--DATE_SIM_RESET\s*-->/gi;
const STARTUP_MENU_PATTERN = /<!--DATE_SIM_STARTUP_MENU_V1\s*-->/gi;
const CANONICAL_PATTERN = /\n?<date_simulator_continuity_engine\b[\s\S]*?<\/date_simulator_continuity_engine>\n?/gi;
const CASE_SAMPLER_PATTERN = /\n?<date_simulator_case_sampler\b[\s\S]*?<\/date_simulator_case_sampler>\n?/gi;
const SAVED_CASE_FALLBACK_PATTERN = /<date_simulator_saved_case_fallback\b[^>]*>[\s\S]*?<\/date_simulator_saved_case_fallback>/gi;

const CASE_FIELDS = [
  "CASE",
  "MAN",
  "WOMAN",
  "DISPOSITION",
  "PREFERENCES",
  "RELATIONSHIP",
  "CURRENT CONTEXT",
  "BOUNDARIES",
  "INITIAL STATE",
];

function normalizeNewlines(value) {
  return String(value ?? "").replace(/\r\n?/g, "\n");
}

function validateFlatCapsuleDetailed(body, fields, maximumLength) {
  const normalized = normalizeNewlines(body).trim();
  if (!normalized) return { value: null, error: "The private profile is empty." };
  if (normalized.length > maximumLength) {
    return { value: null, error: `The private profile exceeds ${maximumLength} characters.` };
  }
  if (normalized.includes("<!--") || normalized.includes("-->")) {
    return { value: null, error: "The private profile contains nested managed markup." };
  }
  const lines = normalized
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  if (lines.length !== fields.length) {
    return { value: null, error: `The private profile must contain exactly ${fields.length} populated fields.` };
  }
  const result = [];
  for (let index = 0; index < fields.length; index += 1) {
    const prefix = `${fields[index]}:`;
    if (!lines[index].startsWith(prefix)) {
      return { value: null, error: `Expected private-profile field ${fields[index]} at position ${index + 1}.` };
    }
    const value = lines[index].slice(prefix.length).trim();
    if (!value) return { value: null, error: `Private-profile field ${fields[index]} is empty.` };
    result.push(`${prefix} ${value}`);
  }
  return { value: result.join("\n"), error: "" };
}

function validateCaseCapsule(body) {
  return validateCaseCapsuleDetailed(body).value;
}

function validateCaseCapsuleDetailed(body) {
  return validateFlatCapsuleDetailed(body, CASE_FIELDS, 24_000);
}

function contentToText(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      if (!part || typeof part !== "object" || part.type !== "text") return "";
      if (typeof part.text === "string") return part.text;
      if (typeof part.content === "string") return part.content;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

function mapTextContent(content, transform) {
  if (typeof content === "string") return transform(content);
  if (!Array.isArray(content)) return content;
  return content.map((part) => {
    if (!part || typeof part !== "object" || part.type !== "text") return part;
    if (typeof part.text === "string") return { ...part, text: transform(part.text) };
    if (typeof part.content === "string") return { ...part, content: transform(part.content) };
    return part;
  });
}

function stripManagedText(text) {
  return normalizeNewlines(text)
    .replace(new RegExp(CANONICAL_PATTERN.source, CANONICAL_PATTERN.flags), "")
    .replace(new RegExp(CASE_PATTERN.source, CASE_PATTERN.flags), "")
    .replace(new RegExp(LEGACY_SCENE_PATTERN.source, LEGACY_SCENE_PATTERN.flags), "")
    .replace(new RegExp(RESET_PATTERN.source, RESET_PATTERN.flags), "")
    .replace(new RegExp(STARTUP_MENU_PATTERN.source, STARTUP_MENU_PATTERN.flags), "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function hashToken(value) {
  let hash = 2166136261;
  const token = String(value ?? "");
  for (let index = 0; index < token.length; index += 1) {
    hash ^= token.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

const EXPLICIT_SURPRISE_COMMAND = /^\s*(?:surprise\s+me|1\s*[.)-]?\s+surprise\s+me)[.!]?\s*$/i;
const NUMERIC_ONE_COMMAND = /^\s*1[.!]?\s*$/;
const SAMPLE_AXES = Object.freeze({
  relationshipSituation: [
    "single and not currently dating",
    "single and casually dating",
    "recently separated or divorced",
    "undefined or complicated",
    "exclusively partnered, engaged, or married",
    "consensually non-monogamous or open",
  ],
  practicalAvailability: [
    "open in principle to dating if interest develops",
    "available in principle but not seeking a connection in this scene",
    "open only to ordinary or platonic interaction in this scene",
    "availability constrained by commitments, timing, or relationship agreements",
    "practical availability uncertain and discoverable only through play",
  ],
  initialAttention: [
    "occupied and initially unaware",
    "aware but self-contained",
    "briefly courteous",
    "open to light situational conversation",
    "independently attentive for a grounded reason",
  ],
  willingnessToEngage: [
    "low unless the interaction becomes relevant",
    "limited but polite",
    "ordinary and context-dependent",
    "moderately open without romantic presumption",
    "socially motivated for her own reason",
  ],
  opportunity: [
    "ordinary public proximity with no manufactured pretext",
    "shared practical task or role",
    "friend or group introduction",
    "scheduled first date or limited prior app contact",
    "community, hobby, or volunteer activity",
    "travel, errand, or routine third-place encounter",
  ],
  timePressure: [
    "little immediate time pressure",
    "a normal finite window",
    "a clear commitment later in the scene",
    "meaningful distraction or competing priority",
  ],
  initiationSupport: [
    "the man normally has the first voluntary social move",
    "either person may initiate because of shared context",
    "the woman may initiate from a practical need or role",
    "the woman may initiate because she independently wants to socialize",
  ],
  dailyContext: [
    "manual, trade, transport, or technical work",
    "service, retail, hospitality, or care work",
    "administrative, public-sector, or office work",
    "student, training, caregiving, or between-work life",
    "small business, freelance, seasonal, or creative work",
    "another ordinary livelihood not overrepresented in recent cases",
  ],
  socialEnergy: [
    "quiet or depleted",
    "reserved but functional",
    "ordinary and variable",
    "warm in context",
    "energetic or outgoing",
  ],
  settingFamily: [
    "urban everyday setting",
    "suburban everyday setting",
    "small-town everyday setting",
    "rural or regional community setting",
    "transit or travel setting",
    "organized social, hobby, or community setting",
  ],
  preferenceAlignment: [
    "strongly unfavorable preference fit while attraction remains possible",
    "somewhat unfavorable preference fit",
    "natural broadly sampled fit",
    "somewhat favorable preference fit",
    "strongly favorable preference fit without established attraction",
  ],
});

function precedingAssistantMessage(messages, userIndex) {
  for (let index = userIndex - 1; index >= 0; index -= 1) {
    if (messages[index]?.role === "assistant") return messages[index];
  }
  return null;
}

function stripStartupMenuMarkers(messages) {
  return (messages ?? []).map((message) => {
    if (!message || typeof message !== "object" || message.role !== "assistant") return message;
    return {
      ...message,
      content: mapTextContent(message.content, (text) => {
        const pattern = new RegExp(STARTUP_MENU_PATTERN.source, STARTUP_MENU_PATTERN.flags);
        if (!pattern.test(text)) return text;
        return normalizeNewlines(text)
          .replace(new RegExp(STARTUP_MENU_PATTERN.source, STARTUP_MENU_PATTERN.flags), "")
          .replace(/\n{3,}/g, "\n\n")
          .trim();
      }),
    };
  });
}

function buildSurpriseMeSample(messages, chatId = "") {
  const sourceMessages = messages ?? [];
  const sourceFinalUserIndex = sourceMessages.reduce(
    (latest, message, index) => (message?.role === "user" ? index : latest),
    -1,
  );
  if (sourceFinalUserIndex < 0) return null;
  if (!sourceMessages.some((message) => V15_VERSION_PATTERN.test(contentToText(message?.content)))) {
    return null;
  }
  const command = contentToText(sourceMessages[sourceFinalUserIndex]?.content);
  const explicitSurprise = EXPLICIT_SURPRISE_COMMAND.test(command);
  const numericOne = NUMERIC_ONE_COMMAND.test(command);
  const precedingAssistant = precedingAssistantMessage(sourceMessages, sourceFinalUserIndex);
  const markedStartupMenu = new RegExp(
    STARTUP_MENU_PATTERN.source,
    STARTUP_MENU_PATTERN.flags,
  ).test(contentToText(precedingAssistant?.content));
  if (!explicitSurprise && !(numericOne && markedStartupMenu)) return null;

  const cleanMessages = stripStartupMenuMarkers(sourceMessages).flatMap((message) => {
    if (!message || typeof message !== "object") return [message];
    const rawText = contentToText(message.content);
    const cleaned = {
      ...message,
      content: mapTextContent(message.content, (text) =>
        normalizeNewlines(text).replace(
          new RegExp(CASE_SAMPLER_PATTERN.source, CASE_SAMPLER_PATTERN.flags),
          "",
        )),
    };
    if (
      message.role === "system" &&
      new RegExp(CASE_SAMPLER_PATTERN.source, CASE_SAMPLER_PATTERN.flags).test(rawText) &&
      !contentToText(cleaned.content).trim()
    ) return [];
    return [cleaned];
  });
  const finalUserIndex = cleanMessages.reduce(
    (latest, message, index) => (message?.role === "user" ? index : latest),
    -1,
  );

  let state = hashToken(`${chatId}|${prefixFingerprint(cleanMessages, finalUserIndex)}|v1.5`);
  const draw = (values) => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return values[state % values.length];
  };
  const selections = Object.fromEntries(
    Object.entries(SAMPLE_AXES).map(([key, values]) => [key, draw(values)]),
  );
  const seed = state.toString(16).padStart(8, "0");
  return {
    seed,
    message: {
      role: "system",
      content: `<date_simulator_case_sampler schema_version="1" seed="${seed}">
Private casting draw for this Surprise Me setup branch. Use these as independent starting axes, not a visible checklist, stereotype, or outcome:
${Object.entries(selections).map(([key, value]) => `${key}: ${value}`).join("\n")}

Make the final case coherent. If two axes conflict, preserve relationship agreements, consent, safety, and practical facts; resolve only the minimum conflict without converting it into dissatisfaction, deception, or romantic availability. Do not preselect attraction, success, rejection, contact exchange, sex, or another outcome. Never quote or mention this draw.
</date_simulator_case_sampler>`,
    },
    messages: cleanMessages,
    insertionIndex: finalUserIndex,
  };
}

function isV14Prompt(messages) {
  return (messages ?? []).some((message) => VERSION_PATTERN.test(contentToText(message?.content)));
}

function messageSwipeId(message) {
  const value = message?.swipe_id;
  return Number.isInteger(value) ? value : 0;
}

function checkpointKey(message) {
  return `${String(message?.id ?? "unknown")}::${messageSwipeId(message)}`;
}

function prefixFingerprint(messages, inclusiveIndex) {
  let hash = 2166136261;
  const bounded = (messages ?? []).slice(0, inclusiveIndex + 1);
  for (const message of bounded) {
    const token = `${message?.id ?? ""}:${messageSwipeId(message)}:${message?.role ?? ""}:${contentToText(message?.content)}|`;
    for (let index = 0; index < token.length; index += 1) {
      hash ^= token.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

/**
 * Copy a validated tracker state onto a fork whose copied messages received
 * new ids. Every nonempty provenance id must be mapped; a partial remap would
 * leave the fork pointing back into its source chat and is therefore rejected.
 */
function remapTrackerStateSourceIds(state, messageIdMap) {
  if (!state || typeof state !== "object") return null;
  const entries = messageIdMap instanceof Map
    ? [...messageIdMap.entries()]
    : Object.entries(messageIdMap && typeof messageIdMap === "object" ? messageIdMap : {});
  const ids = new Map();
  const forkedIds = new Set();
  for (const [sourceIdValue, forkedIdValue] of entries) {
    const sourceId = typeof sourceIdValue === "string" ? sourceIdValue.trim() : "";
    const forkedId = typeof forkedIdValue === "string" ? forkedIdValue.trim() : "";
    if (!sourceId || !forkedId || ids.has(sourceId) || forkedIds.has(forkedId)) return null;
    ids.set(sourceId, forkedId);
    forkedIds.add(forkedId);
  }
  let complete = true;

  const visit = (value) => {
    if (Array.isArray(value)) return value.map(visit);
    if (!value || typeof value !== "object") return value;
    const result = {};
    for (const [key, child] of Object.entries(value)) {
      if (key === "sourceMessageId" && typeof child === "string" && child) {
        const mapped = ids.get(child);
        if (!mapped) complete = false;
        result[key] = mapped ?? child;
      } else {
        result[key] = visit(child);
      }
    }
    return result;
  };

  const remapped = visit(state);
  return complete ? remapped : null;
}

function deriveTranscriptContext(messages) {
  let caseText = null;
  let caseMessageId = null;
  let caseMessageIndex = -1;
  let legacySceneText = null;
  let resetMessageId = null;
  let resetIndex = -1;
  let epoch = 0;
  let invalidCases = 0;
  let caseError = "";
  let invalidCaseMessageId = null;

  for (let index = 0; index < (messages ?? []).length; index += 1) {
    const message = messages[index];
    if (!message || message.role !== "assistant") continue;
    const text = contentToText(message.content);
    if (!text) continue;

    const markers = [];
    for (const match of text.matchAll(new RegExp(CASE_PATTERN.source, CASE_PATTERN.flags))) {
      markers.push({ kind: "case", at: match.index ?? 0, body: match[1] });
    }
    for (const match of text.matchAll(new RegExp(LEGACY_SCENE_PATTERN.source, LEGACY_SCENE_PATTERN.flags))) {
      markers.push({ kind: "scene", at: match.index ?? 0, body: match[1] });
    }
    for (const match of text.matchAll(new RegExp(RESET_PATTERN.source, RESET_PATTERN.flags))) {
      markers.push({ kind: "reset", at: match.index ?? 0 });
    }
    markers.sort((left, right) => left.at - right.at);

    for (const marker of markers) {
      if (marker.kind === "reset") {
        epoch += 1;
        resetMessageId = String(message.id ?? "");
        resetIndex = index;
        caseText = null;
        caseMessageId = null;
        caseMessageIndex = -1;
        legacySceneText = null;
        invalidCaseMessageId = null;
      } else if (marker.kind === "case") {
        const validation = validateCaseCapsuleDetailed(marker.body);
        if (!validation.value) {
          invalidCases += 1;
          caseError = validation.error;
          invalidCaseMessageId = String(message.id ?? "");
          continue;
        }
        caseText = validation.value;
        caseMessageId = String(message.id ?? "");
        caseMessageIndex = index;
        legacySceneText = null;
        caseError = "";
        invalidCaseMessageId = null;
      } else if (marker.kind === "scene" && caseText) {
        legacySceneText = normalizeNewlines(marker.body).trim();
      }
    }
  }

  return {
    active: Boolean(caseText),
    caseText,
    caseMessageId,
    caseMessageIndex,
    legacySceneText,
    resetMessageId,
    resetIndex,
    epoch,
    epochKey: `${epoch}:${resetMessageId ?? "root"}:${caseMessageId ?? "none"}`,
    invalidCases,
    caseError,
    invalidCaseMessageId,
    migrationRequired: Boolean(caseText && legacySceneText),
  };
}

function precedingUser(messages, assistantIndex) {
  for (let index = assistantIndex - 1; index >= 0; index -= 1) {
    if (messages[index]?.role === "user") return { message: messages[index], index };
  }
  return { message: null, index: -1 };
}

const NON_TRACKING_COMMAND = /^\s*\/(?:look|scene|debrief|new)\b/i;

function listEligibleTurns(messages, context) {
  if (!context?.active) return [];
  const turns = [];
  for (let index = Math.max(0, context.caseMessageIndex); index < messages.length; index += 1) {
    const assistant = messages[index];
    if (!assistant || assistant.role !== "assistant") continue;
    const raw = contentToText(assistant.content);
    const publicText = stripManagedText(raw);
    if (
      !publicText ||
      new RegExp(RESET_PATTERN.source, RESET_PATTERN.flags).test(raw)
    ) continue;
    const user = precedingUser(messages, index);
    const userText = contentToText(user.message?.content);
    if (NON_TRACKING_COMMAND.test(userText)) continue;
    turns.push({
      assistant,
      assistantIndex: index,
      assistantText: publicText,
      user: user.message,
      userIndex: user.index,
      userText,
      key: checkpointKey(assistant),
      fingerprint: prefixFingerprint(messages, index),
    });
  }
  return turns;
}

function transcriptForMigration(messages, context, maximumMessages = 24) {
  const start = Math.max(context?.caseMessageIndex ?? 0, messages.length - maximumMessages);
  return messages
    .slice(start)
    .filter((message) => message?.role === "user" || message?.role === "assistant")
    .map((message) => `${message.role.toUpperCase()}: ${stripManagedText(contentToText(message.content))}`)
    .filter((line) => !/:\s*$/.test(line))
    .join("\n\n");
}

function createStore(chatId) {
  return {
    schemaVersion: 2,
    chatId: String(chatId),
    epochKey: "",
    caseText: "",
    current: null,
    checkpoints: {},
    revision: 0,
    migrationAccepted: false,
    migrationRequired: false,
    migrationBaselineKey: "",
    migrationBaselineFingerprint: "",
    processing: false,
    lastError: "",
    lastWarning: "",
    lastRevisionAt: "",
  };
}

function normalizeStore(value, chatId) {
  const fallback = createStore(chatId);
  if (!value || typeof value !== "object" || ![1, 2].includes(value.schemaVersion)) return fallback;
  const result = {
    ...fallback,
    ...value,
    schemaVersion: 2,
    chatId: String(chatId),
    checkpoints: value.checkpoints && typeof value.checkpoints === "object" ? value.checkpoints : {},
  };
  if (result.current) {
    const validated = upgradeTrackerState(result.current, {
      allowedSourceMessageIds: trackerSourceMessageIds(result.current),
    });
    result.current = validated;
  }
  result.checkpoints = Object.fromEntries(
    Object.entries(result.checkpoints).flatMap(([key, checkpoint]) => {
      const state = upgradeTrackerState(checkpoint?.state, {
        allowedSourceMessageIds: trackerSourceMessageIds(checkpoint?.state),
      });
      return state ? [[key, { ...checkpoint, state }]] : [];
    }),
  );
  return result;
}

function selectCheckpoint(store, turn) {
  const checkpoint = store?.checkpoints?.[turn.key];
  if (!checkpoint || checkpoint.fingerprint !== turn.fingerprint) return null;
  const state = upgradeTrackerState(checkpoint.state, {
    allowedSourceMessageIds: trackerSourceMessageIds(checkpoint.state),
  });
  return state ? { ...checkpoint, state } : null;
}

function latestValidCheckpoint(store, turns, beforeIndex = Number.POSITIVE_INFINITY) {
  let latest = null;
  for (let index = 0; index < turns.length && index < beforeIndex; index += 1) {
    const checkpoint = selectCheckpoint(store, turns[index]);
    if (checkpoint) latest = { checkpoint, turnIndex: index };
  }
  return latest;
}

function compactPromptValue(value, defaultValue = "") {
  if (typeof value !== "string") return "";
  const compacted = value.replace(/\s+/g, " ").trim();
  const compactedDefault = typeof defaultValue === "string"
    ? defaultValue.replace(/\s+/g, " ").trim()
    : "";
  const comparable = (text) => text.toLowerCase().replace(/\.$/, "");
  return !compacted || comparable(compacted) === comparable(compactedDefault) ? "" : compacted;
}

function compactPromptFields(entries) {
  return entries.flatMap(([label, value, defaultValue]) => {
    const compacted = compactPromptValue(value, defaultValue);
    return compacted ? [`${label}: ${compacted}`] : [];
  }).join("; ");
}

function compactLifecycle(value) {
  const status = compactPromptValue(value?.status) || "active";
  const reason = compactPromptValue(value?.reason);
  return reason ? `${status}; REASON: ${reason}` : status;
}

function buildCompactPromptState(trackerState) {
  const state = trackerState ?? cloneEmptyState();
  const defaults = cloneEmptyState();
  const scene = state.scene ?? {};
  const arc = state.arc ?? {};
  const lines = ["CURRENT SCENE", `LIFECYCLE: ${compactLifecycle(scene.lifecycle)}`];
  const when = [
    compactPromptValue(scene.date, defaults.scene.date),
    compactPromptValue(scene.time, defaults.scene.time),
  ].filter(Boolean).join("; ");
  if (when) lines.push(`WHEN: ${when}`);

  for (const [label, value, defaultValue] of [
    ["WEATHER", scene.weather, defaults.scene.weather],
    ["LOCATION", scene.location, defaults.scene.location],
    ["CONTEXT", scene.immediateContext, defaults.scene.immediateContext],
  ]) {
    const compacted = compactPromptValue(value, defaultValue);
    if (compacted) lines.push(`${label}: ${compacted}`);
  }

  for (const [label, fields] of [
    ["WOMAN STABLE", [
      ["FACE", scene.womanStable?.face, defaults.scene.womanStable.face],
      ["EYES", scene.womanStable?.eyes, defaults.scene.womanStable.eyes],
      ["SKIN", scene.womanStable?.skin, defaults.scene.womanStable.skin],
      ["BODY TYPE & PROPORTIONS", scene.womanStable?.bodyTypeAndProportions, defaults.scene.womanStable.bodyTypeAndProportions],
    ]],
    ["WOMAN CURRENT", [
      ["HAIR & GROOMING", scene.womanCurrent?.hairAndGrooming, defaults.scene.womanCurrent.hairAndGrooming],
      ["DRESS & LAYERS", scene.womanCurrent?.dress, defaults.scene.womanCurrent.dress],
      ["PHYSICAL STATE", scene.womanCurrent?.physicalState, defaults.scene.womanCurrent.physicalState],
      ["MENTAL STATE", scene.womanCurrent?.mentalState, defaults.scene.womanCurrent.mentalState],
    ]],
    ["MAN VISIBLE", [
      ["APPEARANCE", scene.manVisible?.appearance, defaults.scene.manVisible.appearance],
      ["DRESS & LAYERS", scene.manVisible?.dressAndLayers, defaults.scene.manVisible.dressAndLayers],
      ["PHYSICAL STATE", scene.manVisible?.physicalState, defaults.scene.manVisible.physicalState],
    ]],
    ["SPATIAL", [
      ["WOMAN POSITION", scene.spatial?.womanPosition, defaults.scene.spatial.womanPosition],
      ["MAN POSITION", scene.spatial?.manPosition, defaults.scene.spatial.manPosition],
      ["PROXIMITY & CONTACT", scene.spatial?.proximityAndContact, defaults.scene.spatial.proximityAndContact],
      ["IMPORTANT ITEMS", scene.spatial?.importantItems, defaults.scene.spatial.importantItems],
    ]],
  ]) {
    const compacted = compactPromptFields(fields);
    if (compacted) lines.push(`${label}: ${compacted}`);
  }

  lines.push("", "CURRENT ARC", `LIFECYCLE: ${compactLifecycle(arc.lifecycle)}`);

  for (const [index, npc] of (Array.isArray(arc.npcs) ? arc.npcs : []).entries()) {
    const compacted = compactPromptFields([
      ["NAME", npc?.name],
      ["ROLE", npc?.role],
      ["RELATIONSHIP", npc?.relationship],
      ["STATUS", npc?.currentStatus],
      ["IMMEDIATE OBJECTIVE", npc?.immediateObjective],
    ]);
    if (compacted) lines.push(`NPC ${index + 1}: ${compacted}`);
  }

  const relationship = compactPromptFields([
    ["ESTABLISHED STATUS", arc.relationship?.establishedStatus, defaults.arc.relationship.establishedStatus],
    ["WOMAN POSTURE", arc.relationship?.womanPosture, defaults.arc.relationship.womanPosture],
    ["BOUNDARY OR CONCERN", arc.relationship?.activeBoundaryOrConcern, defaults.arc.relationship.activeBoundaryOrConcern],
    ["LATEST CHANGE", arc.relationship?.latestChange, defaults.arc.relationship.latestChange],
  ]);
  if (relationship) lines.push(`RELATIONSHIP: ${relationship}`);

  const response = compactPromptFields([
    ["AVAILABLE ATTENTION", arc.response?.availableAttention, defaults.arc.response.availableAttention],
    ["COMFORT & SAFETY", arc.response?.comfortAndSafety, defaults.arc.response.comfortAndSafety],
    ["RAPPORT & TRUST", arc.response?.rapportAndTrust, defaults.arc.response.rapportAndTrust],
    ["PHYSICAL ATTRACTION", arc.response?.physicalAttraction, defaults.arc.response.physicalAttraction],
    ["PERSONAL INTEREST", arc.response?.personalInterest, defaults.arc.response.personalInterest],
    ["ROMANTIC INTEREST", arc.response?.romanticInterest, defaults.arc.response.romanticInterest],
    ["SEXUAL INTEREST", arc.response?.sexualInterest, defaults.arc.response.sexualInterest],
    ["WILLINGNESS TO CONTINUE", arc.response?.willingnessToContinue, defaults.arc.response.willingnessToContinue],
    ["CONTACT-EXCHANGE INTEREST", arc.response?.contactExchangeInterest, defaults.arc.response.contactExchangeInterest],
    ["DESIRE TO LEAVE", arc.response?.desireToLeave, defaults.arc.response.desireToLeave],
    ["ACTIVE UNCERTAINTY", arc.response?.activeUncertainty, defaults.arc.response.activeUncertainty],
    ["LATEST CHANGE", arc.response?.latestChange, defaults.arc.response.latestChange],
  ]);
  if (response) lines.push(`PRIVATE RESPONSE: ${response}`);

  for (const [index, objective] of (Array.isArray(arc.objectives) ? arc.objectives : []).entries()) {
    const compacted = compactPromptFields([
      ["OWNER", objective?.owner],
      ["OBJECTIVE", objective?.objective],
      ["STATUS", objective?.status],
      ["TIMING", objective?.timing],
    ]);
    if (compacted) lines.push(`OBJECTIVE ${index + 1}: ${compacted}`);
  }

  lines.push(
    "",
    "Any omitted CURRENT SCENE or CURRENT ARC field is unknown, empty, or has no tracked entry. Do not infer omitted facts. Provenance remains internal.",
  );
  return lines.join("\n");
}

function buildCanonicalState(caseText, trackerState, status = "active") {
  return `<date_simulator_continuity_engine schema_version="${TRACKER_SCHEMA_VERSION}" status="${status}">
The Continuity Engine is active for this request. This is private canonical state for the selected chat branch. Use it for continuity but never quote, expose, or mention it. The public roleplay response must not contain DATE_SIM_SCENE or DATE_SIM_ARC bookkeeping.

STABLE CASE
${caseText || "Unavailable. Use only explicit transcript facts."}

${buildCompactPromptState(trackerState)}
</date_simulator_continuity_engine>`;
}

function compactPromptMessages(messages, caseText, trackerState, status = "active") {
  const compacted = (messages ?? []).map((message) => {
    if (!message || typeof message !== "object") return message;
    if (message.role === "assistant") {
      return { ...message, content: mapTextContent(message.content, stripManagedText) };
    }
    if (message.role === "system") {
      return {
        ...message,
        content: mapTextContent(message.content, (text) =>
          normalizeNewlines(text).replace(
            new RegExp(
              SAVED_CASE_FALLBACK_PATTERN.source,
              SAVED_CASE_FALLBACK_PATTERN.flags,
            ),
            "[managed by Date Simulator Continuity Engine]",
          ),
        ),
      };
    }
    return message;
  });

  const insertionIndex = Math.max(
    0,
    compacted.reduce((latest, message, index) => (message?.role === "user" ? index : latest), -1),
  );
  compacted.splice(insertionIndex, 0, {
    role: "system",
    content: buildCanonicalState(caseText, trackerState, status),
  });
  return { messages: compacted, injectionIndex: insertionIndex };
}


const DEFAULT_TRACKER_TIMEOUT_MS = 30_000;
const MIN_TRACKER_TIMEOUT_MS = 5_000;
const MAX_TRACKER_TIMEOUT_MS = 120_000;
const DEFAULT_TRACKER_MAX_TOKENS = 2_000;
const MIN_TRACKER_MAX_TOKENS = 400;
const MAX_TRACKER_MAX_TOKENS = 2_000;
const DEFAULT_TRACKER_OUTPUT_MODE = "auto";
const TRACKER_OUTPUT_MODES = Object.freeze(["auto", "openai", "anthropic", "plain"]);

function normalizeTrackerTimeoutMs(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return DEFAULT_TRACKER_TIMEOUT_MS;
  return Math.max(MIN_TRACKER_TIMEOUT_MS, Math.min(MAX_TRACKER_TIMEOUT_MS, Math.round(parsed)));
}

const TRACKER_SYSTEM_PROMPT = `You are the private continuity recorder for Date Simulator. Update a compact current-state ledger from canonical prior state and one newly completed public roleplay turn.

Hard rules:
- Record consequences of the supplied turn; never create new dialogue, actions, events, NPC activity, promises, consent, or public story developments.
- Preserve an established value unless the new turn directly changes or corrects it. Use "Unknown" instead of guessing.
- scene.date and scene.time are the fictional narrative clock, never wall-clock time. Ignore message timestamps, response delay, generation latency, and how long the user waited in real life. Advance narrative time by the duration explicitly stated or conservatively implied by completed public dialogue and action, including a small plausible advance for exchanges that clearly consume time. Narratively implied passage counts as a supported direct change to date/time even when nobody states a clock value. Preserve approximate wording when exact precision is unavailable, do not advance for a purely observational or analytical command, and update the date when narrated time crosses midnight.
- scene.lifecycle records only whether the current scene is active or ended. arc.lifecycle separately records whether the larger relationship arc is active or ended. A scene may end while its arc remains active because a future meeting or continuing connection is established. For each lifecycle use action "preserve" unless its status or reason changes; use action "update" when it changes. Starting a later scene replaces the prior current scene and sets scene.lifecycle to active without creating scene history.
- The user controls the man. Never invent his thoughts, feelings, motives, attraction, consent, body, outfit, position, or voluntary action. You may record only facts the user explicitly established or direct physical consequences already narrated.
- womanStable contains stable observable appearance copied conservatively from the stable case and public opening: face structure and enduring facial features; visible eye color, shape, and other enduring eye traits; visible skin tone, complexion, and enduring marks; and nonsexualized body type, frame, and proportions. Preserve these fields unless the transcript explicitly corrects them or establishes a plausible lasting change. Never infer a trait from ethnicity, ancestry, nationality, culture, personality, clothing, or attraction; use "Unknown" for anything the case and public scene do not establish.
- womanCurrent contains only temporary hair/grooming, dress/layer state, physical condition, and current mental state or immediate intent. Expressions, makeup, temporary skin changes, posture, weight change, and other current or changing presentation belong here or in spatial when supported; do not overwrite womanStable with them.
- manVisible separates currently relevant visible appearance, clothing/layer state, and temporary physical condition explicitly established by the user or directly caused by canonical events. Preserve established facts until changed, use "Unknown" for anything unset, and never infer a body detail, outfit, condition, position, or voluntary action.
- spatial separately preserves the woman's position, the man's explicitly established position, proximity/contact, and important held or carried items. Never invent the man's movement or position. Nothing moves, appears, disappears, opens, closes, transfers, or changes contact without a canonical cause.
- Mental state is temporary mood or immediate intent. ARC RESPONSE separately preserves the woman's qualitative private response to this man: attention, comfort/safety, rapport/trust, physical attraction, personal interest, romantic interest, adult sexual interest, willingness to continue, contact-exchange interest, desire to leave, and active uncertainty.
- Update private response only when the stable profile plus canonical observable interaction directly supports a conservative change. Change only affected dimensions, normally by one qualitative step; use mixed or uncertain language when evidence conflicts. This records private continuity and does not create a public event.
- Consent is action-specific and is never a response field or an inference from attraction, comfort, prior willingness, clothing, physiology, or silence. Teen Mode sexualInterest must be "Not applicable in Teen Mode."
- Never use numbers, points, percentages, scores, or game meters in private response fields. Never convert private response into visible behavior unless the public turn independently established that behavior.
- NPCS includes named or plausibly recurring NPCs only. Return the complete current NPC list. For each exactly unchanged NPC copy its fields and use action "preserve". For a new or materially updated NPC use action "update". Omit an NPC only when it is no longer plausibly recurring. Do not add incidental staff or passersby.
- OBJECTIVES contains at most three immediate plans, commitments, pressures, or intended next steps. Return the complete current objective list. timing records an established deadline, planned date, or practical window, otherwise "Unknown". Never infer an objective for the man unless he stated it. For each exactly unchanged objective copy its fields and use action "preserve". For a new or materially updated objective use action "update". Omit an objective only when it no longer belongs in the current list.
- If no relationship field changed, copy the prior relationship fields and latestChange and use action "preserve". If a relationship field changed, use action "update" and write one concise nonempty latestChange summary.
- If no private-response dimension changed, copy the prior response fields and latestChange and use action "preserve". If a supported response dimension changed, use action "update" and write one concise nonempty latestChange summarizing only the changed dimensions.
- action is processing metadata, not story state. Use only "preserve" or "update". Never return sourceMessageId; provenance is assigned by the extension after generation.
- Return only the JSON object required by the schema. No markdown or commentary.

Required JSON shape (every shown property is required; npcs and objectives may be empty arrays):
{"schemaVersion":4,"scene":{"date":"string","time":"string","weather":"string","location":"string","immediateContext":"string","lifecycle":{"status":"active or ended","reason":"string or empty","action":"preserve or update"},"womanStable":{"face":"string","eyes":"string","skin":"string","bodyTypeAndProportions":"string"},"womanCurrent":{"hairAndGrooming":"string","dress":"string","physicalState":"string","mentalState":"string"},"manVisible":{"appearance":"string","dressAndLayers":"string","physicalState":"string"},"spatial":{"womanPosition":"string","manPosition":"string","proximityAndContact":"string","importantItems":"string"}},"arc":{"lifecycle":{"status":"active or ended","reason":"string or empty","action":"preserve or update"},"npcs":[{"name":"string","role":"string","relationship":"string","currentStatus":"string","immediateObjective":"string","action":"preserve or update"}],"relationship":{"establishedStatus":"string","womanPosture":"string","activeBoundaryOrConcern":"string","latestChange":"string or empty","action":"preserve or update"},"response":{"availableAttention":"string","comfortAndSafety":"string","rapportAndTrust":"string","physicalAttraction":"string","personalInterest":"string","romanticInterest":"string","sexualInterest":"string","willingnessToContinue":"string","contactExchangeInterest":"string","desireToLeave":"string","activeUncertainty":"string","latestChange":"string or empty","action":"preserve or update"},"objectives":[{"owner":"string","objective":"string","status":"string","timing":"string","action":"preserve or update"}]}}`;

function trackerUserPrompt({ caseText, previousState, userText, assistantText }) {
  return `STABLE PRIVATE CASE
${caseText}

PREVIOUS TRACKER STATE (provenance removed; existing actions are preserve markers)
${JSON.stringify(trackerStateForLlm(previousState))}

NEW USER TURN
${userText || "[No preceding user turn; this is the generated opening.]"}

NEW PUBLIC ASSISTANT TURN
${assistantText}

Produce schemaVersion ${TRACKER_SCHEMA_VERSION} state now.`;
}

function migrationUserPrompt({ caseText, legacySceneText, transcript }) {
  return `This is an explicit migration from Date Simulator v1.3.1. Build one conservative current tracker state from the saved case, latest legacy scene, and selected recent transcript. Do not add facts that are absent or resolve ambiguous relationship or private-response state.

STABLE PRIVATE CASE
${caseText}

LATEST LEGACY SCENE
${legacySceneText || "Unavailable"}

RECENT SELECTED TRANSCRIPT
${transcript || "Unavailable"}

Produce schemaVersion ${TRACKER_SCHEMA_VERSION} state now.`;
}

function extractJson(text) {
  const raw = String(text ?? "").trim();
  if (!raw) return null;
  const candidates = [raw];
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) candidates.push(fenced[1].trim());
  const first = raw.indexOf("{");
  const last = raw.lastIndexOf("}");
  if (first >= 0 && last > first) candidates.push(raw.slice(first, last + 1));
  for (const candidate of candidates) {
    try {
      return JSON.parse(candidate);
    } catch {
      // Try the next bounded representation.
    }
  }
  return null;
}

function resolveOutputMode(connection, requestedMode = DEFAULT_TRACKER_OUTPUT_MODE) {
  if (TRACKER_OUTPUT_MODES.includes(requestedMode) && requestedMode !== "auto") return requestedMode;
  const provider = [
    connection?.provider,
    connection?.type,
    connection?.kind,
    connection?.protocol,
    connection?.apiType,
    connection?.format,
  ].map((value) => String(value ?? "")).join(" ").toLowerCase();
  if (provider.includes("google") || provider.includes("gemini")) return "google";
  if (provider.includes("anthropic") || provider.includes("claude")) return "anthropic";
  if (
    provider.includes("openai") ||
    provider.includes("openrouter") ||
    provider.includes("nanogpt") ||
    provider.includes("deepseek")
  ) return "openai";
  return "plain";
}

function generationParameters(connection, outputMode = DEFAULT_TRACKER_OUTPUT_MODE) {
  const base = { temperature: 0, top_p: 0.1, max_tokens: DEFAULT_TRACKER_MAX_TOKENS };
  const mode = resolveOutputMode(connection, outputMode);
  if (mode === "google") {
    return { ...base, responseMimeType: "application/json", responseSchema: TRACKER_OUTPUT_JSON_SCHEMA };
  }
  if (mode === "openai") {
    return {
      ...base,
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "date_simulator_continuity_state",
          strict: true,
          schema: TRACKER_OUTPUT_JSON_SCHEMA,
        },
      },
    };
  }
  if (mode === "anthropic") {
    return {
      ...base,
      tool_choice: { type: "tool", name: "record_date_simulator_state" },
    };
  }
  return base;
}

function generationTools(connection, outputMode = DEFAULT_TRACKER_OUTPUT_MODE) {
  if (resolveOutputMode(connection, outputMode) !== "anthropic") return undefined;
  return [
    {
      name: "record_date_simulator_state",
      description: "Return the complete validated Date Simulator continuity state.",
      parameters: TRACKER_OUTPUT_JSON_SCHEMA,
    },
  ];
}

async function resolveConnection(spindleApi, connectionId, userId) {
  if (!connectionId) {
    try {
      const connections = await spindleApi.connections.list(userId);
      return connections.find((connection) => connection?.is_default) ?? null;
    } catch {
      return null;
    }
  }
  try {
    return await spindleApi.connections.get(connectionId, userId);
  } catch {
    return null;
  }
}

async function generateCandidate(spindleApi, messages, config, sourceMessageId, previousState, caseText, userId) {
  const connection = await resolveConnection(spindleApi, config.connectionId, userId);
  const allowedSourceMessageIds = [
    sourceMessageId,
    ...trackerSourceMessageIds(previousState),
  ].filter(Boolean);
  const makeRequest = (attemptMessages) => {
    const input = {
      type: "quiet",
      messages: attemptMessages,
      parameters: {
        ...generationParameters(connection, config.outputMode),
        max_tokens: Math.max(
          MIN_TRACKER_MAX_TOKENS,
          Math.min(
            MAX_TRACKER_MAX_TOKENS,
            Number(config.maxTokens) || DEFAULT_TRACKER_MAX_TOKENS,
          ),
        ),
      },
      reasoning: { source: "off" },
      signal: AbortSignal.timeout(normalizeTrackerTimeoutMs(config.timeoutMs)),
    };
    const tools = generationTools(connection, config.outputMode);
    if (tools) input.tools = tools;
    // Lumiverse scopes direct generation through GenerationRequestDTO.userId.
    // Connection profile methods instead accept userId as a positional argument.
    if (userId) input.userId = userId;
    if (config.connectionId) input.connection_id = config.connectionId;
    return input;
  };
  const validateResponse = (response) => {
    const toolState = response?.tool_calls?.find(
      (call) => call?.name === "record_date_simulator_state",
    )?.args;
    const parsed = toolState && typeof toolState === "object"
      ? toolState
      : extractJson(toolState ?? response?.content);
    return {
      parsed,
      validation: recoverTrackerOutputDetailed(parsed, {
        previousState,
        sourceMessageId,
        allowedSourceMessageIds,
        teenMode: /\bTeen Mode\b/i.test(String(caseText ?? "")),
      }),
    };
  };

  let response = await spindleApi.generate.quiet(makeRequest(messages));
  let { parsed, validation } = validateResponse(response);
  if (!validation.state) {
    const rejectedText = parsed && typeof parsed === "object"
      ? JSON.stringify(parsed)
      : String(response?.content ?? "").trim();
    const repairPrompt = {
      role: "user",
      content: `Repair the rejected tracker object because: ${validation.error}.

Return one complete replacement object. It must conform to this JSON Schema:
${JSON.stringify(TRACKER_OUTPUT_JSON_SCHEMA)}

Preserve canonical facts, use Unknown rather than guessing, and return no prose or markdown.`,
    };
    const rejectedAssistant = {
      role: "assistant",
      content: rejectedText || "[The prior response contained no usable JSON object.]",
    };
    response = await spindleApi.generate.quiet(makeRequest([...messages, rejectedAssistant, repairPrompt]));
    ({ validation } = validateResponse(response));
  }
  if (!validation.state) {
    const finishReason = String(response?.finish_reason ?? "unknown").replace(/[^a-zA-Z0-9_.-]/g, "_");
    const contentLength = String(response?.content ?? "").length;
    const toolCallCount = Array.isArray(response?.tool_calls) ? response.tool_calls.length : 0;
    throw new Error(
      `Tracker state rejected after repair: ${validation.error}; finish=${finishReason}; contentChars=${contentLength}; toolCalls=${toolCallCount}.`,
    );
  }
  return { state: validation.state, warnings: validation.warnings ?? [] };
}

async function runTracker(spindleApi, input, config, userId) {
  return generateCandidate(
    spindleApi,
    [
      { role: "system", content: TRACKER_SYSTEM_PROMPT },
      { role: "user", content: trackerUserPrompt(input) },
    ],
    config,
    input.sourceMessageId,
    input.previousState,
    input.caseText,
    userId,
  );
}

async function runMigrationTracker(spindleApi, input, config, userId) {
  return generateCandidate(
    spindleApi,
    [
      { role: "system", content: TRACKER_SYSTEM_PROMPT },
      { role: "user", content: migrationUserPrompt(input) },
    ],
    config,
    input.sourceMessageId,
    null,
    input.caseText,
    userId,
  );
}

const trackerTest = Object.freeze({
  systemPrompt: TRACKER_SYSTEM_PROMPT,
  extractJson,
  generationParameters,
  generationTools,
  resolveOutputMode,
  trackerUserPrompt,
  migrationUserPrompt,
  normalizeTrackerTimeoutMs,
});


const DEFAULT_CONFIG = Object.freeze({
  enabled: true,
  showStatusWidget: true,
  connectionId: "",
  maxTokens: DEFAULT_TRACKER_MAX_TOKENS,
  timeoutMs: DEFAULT_TRACKER_TIMEOUT_MS,
  outputMode: DEFAULT_TRACKER_OUTPUT_MODE,
});

const queues = new Map();
const userByChat = new Map();
const activeChatByUser = new Map();
const deletedChats = new Set();
const pendingCleanupByUser = new Map();
let interceptorRegistered = false;
let activeChatId = null;
let frontendUserId = undefined;

const CLEANUP_CONFIRMATION_TTL_MS = 2 * 60 * 1000;

function validUserId(userId) {
  return typeof userId === "string" && Boolean(userId.trim());
}

function adoptActiveChat(chatId, userId) {
  if (typeof chatId === "string" && chatId.trim()) {
    activeChatId = chatId;
    if (validUserId(userId)) {
      frontendUserId = userId;
      userByChat.set(chatId, userId);
      activeChatByUser.set(userId, chatId);
    }
  }
  if (validUserId(userId)) return activeChatByUser.get(userId) ?? null;
  return activeChatId;
}

function userForChat(chatId, userId) {
  if (validUserId(userId)) {
    frontendUserId = userId;
    if (chatId) userByChat.set(chatId, userId);
    return userId;
  }
  return userByChat.get(chatId) ?? frontendUserId;
}

function boundedInteger(value, fallback, minimum, maximum) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(minimum, Math.min(maximum, Math.round(parsed)));
}

function normalizeConfig(value) {
  const source = value && typeof value === "object" ? value : {};
  return {
    enabled: source.enabled !== false,
    showStatusWidget: source.showStatusWidget !== false,
    connectionId: typeof source.connectionId === "string" ? source.connectionId : "",
    outputMode: TRACKER_OUTPUT_MODES.includes(source.outputMode)
      ? source.outputMode
      : DEFAULT_TRACKER_OUTPUT_MODE,
    maxTokens: boundedInteger(
      source.maxTokens,
      DEFAULT_TRACKER_MAX_TOKENS,
      MIN_TRACKER_MAX_TOKENS,
      MAX_TRACKER_MAX_TOKENS,
    ),
    timeoutMs: boundedInteger(
      source.timeoutMs,
      DEFAULT_TRACKER_TIMEOUT_MS,
      MIN_TRACKER_TIMEOUT_MS,
      MAX_TRACKER_TIMEOUT_MS,
    ),
  };
}

async function loadConfig() {
  const value = await spindle.storage.getJson("config.json", { fallback: DEFAULT_CONFIG });
  return normalizeConfig(value);
}

async function saveConfig(value) {
  const config = normalizeConfig(value);
  await spindle.storage.setJson("config.json", config, { indent: 2 });
  return config;
}

async function saveWidgetVisibility(showStatusWidget) {
  const current = await loadConfig();
  return saveConfig({ ...current, showStatusWidget });
}

function safeChatToken(chatId) {
  return String(chatId ?? "unknown").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 180);
}

function storePath(chatId) {
  return `chats/${safeChatToken(chatId)}.json`;
}

async function loadStore(chatId) {
  const value = await spindle.storage.getJson(storePath(chatId), {
    fallback: createStore(chatId),
  });
  return normalizeStore(value, chatId);
}

async function saveStore(chatId, store) {
  await spindle.storage.setJson(storePath(chatId), store, { indent: 2 });
}

function isInertStore(value) {
  if (!value || typeof value !== "object" || value.processing === true) return false;
  const checkpoints = value.checkpoints && typeof value.checkpoints === "object"
    ? value.checkpoints
    : {};
  return (
    !String(value.caseText ?? "").trim()
    && value.current == null
    && Object.keys(checkpoints).length === 0
    && Number(value.revision ?? 0) === 0
    && value.migrationAccepted !== true
    && value.migrationRequired !== true
    && !String(value.migrationBaselineKey ?? "").trim()
    && !String(value.migrationBaselineFingerprint ?? "").trim()
    && !String(value.lastError ?? "").trim()
    && !String(value.lastWarning ?? "").trim()
    && !String(value.lastRevisionAt ?? "").trim()
  );
}

function cleanupUserKey(userId) {
  return validUserId(userId) ? userId : "__default__";
}

function strictStoreFile(entry) {
  return typeof entry === "string" && /^[a-zA-Z0-9_-]{1,180}\.json$/.test(entry);
}

async function readCleanupStore(entry) {
  if (!strictStoreFile(entry)) return null;
  const path = `chats/${entry}`;
  let raw;
  try {
    raw = await spindle.storage.read(path);
  } catch (error) {
    throw new Error(`Could not read ${path}: ${String(error?.message ?? error)}`);
  }
  let value;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!value || typeof value !== "object" || ![1, 2].includes(value.schemaVersion)) return null;
  const chatId = typeof value.chatId === "string" ? value.chatId.trim() : "";
  if (!chatId || entry !== `${safeChatToken(chatId)}.json`) return null;
  return { path, chatId, value };
}

async function missingChat(chatId) {
  try {
    await spindle.chat.getMessages(chatId);
    return false;
  } catch (error) {
    if (String(error?.message ?? error).trim() === "Chat not found") return true;
    throw error;
  }
}

async function classifyCleanupStore(entry) {
  const parsed = await readCleanupStore(entry);
  if (!parsed) return null;
  let reason = "";
  if (isInertStore(parsed.value)) reason = "inert";
  else if (await missingChat(parsed.chatId)) reason = "orphan";
  if (!reason) return null;
  let sizeBytes = 0;
  try {
    const stat = await spindle.storage.stat(parsed.path);
    sizeBytes = Number.isFinite(Number(stat?.sizeBytes)) ? Number(stat.sizeBytes) : 0;
  } catch {
    // Size is informational; a readable validated file remains a candidate.
  }
  return { ...parsed, reason, sizeBytes };
}

async function scanUnusedStores() {
  const entries = await spindle.storage.list("chats/");
  const result = {
    candidates: [],
    scanned: Array.isArray(entries) ? entries.length : 0,
    skipped: 0,
    errors: 0,
  };
  for (const entry of Array.isArray(entries) ? entries : []) {
    try {
      const candidate = await classifyCleanupStore(entry);
      if (candidate) result.candidates.push(candidate);
      else result.skipped += 1;
    } catch (error) {
      result.errors += 1;
      spindle.log.warn(`Continuity cleanup skipped ${String(entry)}: ${String(error?.message ?? error)}`);
    }
  }
  result.inert = result.candidates.filter((candidate) => candidate.reason === "inert").length;
  result.orphan = result.candidates.filter((candidate) => candidate.reason === "orphan").length;
  result.sizeBytes = result.candidates.reduce((total, candidate) => total + candidate.sizeBytes, 0);
  return result;
}

function forgetChat(chatId) {
  userByChat.delete(chatId);
  for (const [userId, mappedChatId] of activeChatByUser.entries()) {
    if (mappedChatId === chatId) activeChatByUser.delete(userId);
  }
  if (activeChatId === chatId) activeChatId = null;
}

function formatStorageSize(sizeBytes) {
  const bytes = Math.max(0, Number(sizeBytes) || 0);
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10 * 1024 ? 1 : 0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

async function setVariableIfChanged(chatId, key, value) {
  const previous = await spindle.variables.chat.get(chatId, key);
  if (previous !== value) await spindle.variables.chat.set(chatId, key, value);
}

async function mirrorStore(chatId, store, context) {
  const current = store.current;
  const legacyArc = current
    ? {
      npcs: (current.arc?.npcs ?? []).map((npc) => ({
        name: npc.name,
        role: npc.role,
        relationship: npc.relationship,
        currentStatus: npc.currentStatus,
        immediateObjective: npc.immediateObjective,
      })),
      relationship: current.arc?.relationship ?? {},
      objectives: (current.arc?.objectives ?? []).map((objective) => ({
        owner: objective.owner,
        objective: objective.objective,
        status: objective.status,
      })),
    }
    : null;
  await Promise.all([
    setVariableIfChanged(chatId, CHAT_KEYS.case, context.active ? context.caseText : INACTIVE_CASE),
    setVariableIfChanged(chatId, CHAT_KEYS.phase, context.active ? "active" : "setup"),
    setVariableIfChanged(
      chatId,
      CHAT_KEYS.trackerVersion,
      context.active ? String(TRACKER_SCHEMA_VERSION) : "",
    ),
    setVariableIfChanged(chatId, CHAT_KEYS.scene, current ? JSON.stringify(current.scene) : ""),
    setVariableIfChanged(chatId, CHAT_KEYS.arc, current ? JSON.stringify(current.arc) : ""),
    setVariableIfChanged(chatId, CHAT_KEYS.legacyArc, legacyArc ? JSON.stringify(legacyArc) : ""),
    setVariableIfChanged(chatId, CHAT_KEYS.revision, String(store.revision ?? 0)),
  ]);
}

function readiness(config) {
  const missing = ["generation", "interceptor", "chat_mutation"].filter(
    (permission) => !spindle.permissions.has(permission),
  );
  if (!config.enabled) {
    return { level: "amber", code: "disabled", text: "Continuity Engine is installed but disabled." };
  }
  if (missing.length > 0) {
    return {
      level: "amber",
      code: "permissions",
      text: `Continuity Engine needs permission: ${missing.join(", ")}.`,
    };
  }
  return {
    level: "green",
    code: "ready",
    text: "Continuity Engine ready. Open a Date Simulator v1.4.x or v1.5.x chat to begin tracking.",
  };
}

function sendFrontend(payload, userId = frontendUserId) {
  try {
    spindle.sendToFrontend(payload, userId);
  } catch {
    // Frontend may not be connected yet.
  }
}

function publicTrackerSnapshot(state) {
  if (!state || typeof state !== "object") return null;
  const scene = state.scene && typeof state.scene === "object" ? state.scene : {};
  const woman = scene.womanCurrent && typeof scene.womanCurrent === "object"
    ? scene.womanCurrent
    : {};
  const womanStable = scene.womanStable && typeof scene.womanStable === "object"
    ? scene.womanStable
    : {};
  const sceneLifecycle = scene.lifecycle && typeof scene.lifecycle === "object"
    ? scene.lifecycle
    : {};
  const manVisible = scene.manVisible && typeof scene.manVisible === "object"
    ? scene.manVisible
    : {};
  const spatial = scene.spatial && typeof scene.spatial === "object"
    ? scene.spatial
    : {};
  const arc = state.arc && typeof state.arc === "object" ? state.arc : {};
  const arcLifecycle = arc.lifecycle && typeof arc.lifecycle === "object"
    ? arc.lifecycle
    : {};
  const relationship = arc.relationship && typeof arc.relationship === "object"
    ? arc.relationship
    : {};
  const text = (value, fallback = "Unknown") => (
    typeof value === "string" && value.trim() ? value : fallback
  );

  return {
    scene: {
      date: text(scene.date),
      time: text(scene.time),
      weather: text(scene.weather),
      location: text(scene.location),
      immediateContext: text(scene.immediateContext),
      lifecycle: {
        status: text(sceneLifecycle.status, "active"),
      },
      womanStable: {
        face: text(womanStable.face),
        eyes: text(womanStable.eyes),
        skin: text(womanStable.skin),
        bodyTypeAndProportions: text(womanStable.bodyTypeAndProportions),
      },
      womanCurrent: {
        hairAndGrooming: text(woman.hairAndGrooming),
        dress: text(woman.dress),
        physicalState: text(woman.physicalState),
      },
      manVisible: {
        appearance: text(manVisible.appearance),
        dressAndLayers: text(manVisible.dressAndLayers),
        physicalState: text(manVisible.physicalState),
      },
      spatial: {
        womanPosition: text(spatial.womanPosition),
        manPosition: text(spatial.manPosition),
        proximityAndContact: text(spatial.proximityAndContact),
        importantItems: text(spatial.importantItems),
      },
    },
    arc: {
      lifecycle: {
        status: text(arcLifecycle.status, "active"),
      },
      npcs: Array.isArray(arc.npcs)
        ? arc.npcs.map((npc) => ({
          name: text(npc?.name),
          role: text(npc?.role),
          relationship: text(npc?.relationship),
          currentStatus: text(npc?.currentStatus),
        }))
        : [],
      relationship: {
        establishedStatus: text(relationship.establishedStatus, "No relationship status established."),
        latestChange: text(relationship.latestChange, "No recent relationship change."),
      },
    },
  };
}

async function statusPayload(chatId, options = {}) {
  const config = await loadConfig();
  const base = readiness(config);
  if (!chatId) return { type: "continuity_status", ...base, config, chatId: null };
  const store = await loadStore(chatId);
  let caseMessageId = null;
  let profileSaved = false;
  let caseError = "";
  if (spindle.permissions.has("chat_mutation")) {
    try {
      const messages = await spindle.chat.getMessages(chatId);
      const transcript = deriveTranscriptContext(messages);
      caseMessageId = transcript.caseMessageId ?? transcript.invalidCaseMessageId;
      caseError = transcript.caseError;
      profileSaved = Boolean(
        transcript.active &&
        store.caseText === transcript.caseText &&
        store.epochKey === transcript.epochKey
      );
    } catch {
      // Status remains useful without a branch read.
    }
  }
  const payload = {
    type: "continuity_status",
    ...base,
    chatId,
    caseMessageId,
    profileSaved,
    config,
    processing: Boolean(store.processing),
    migrationRequired: Boolean(store.migrationRequired && !store.migrationAccepted),
    lastError: store.lastError || "",
    lastWarning: store.lastWarning || "",
    revision: store.revision || 0,
    lastRevisionAt: store.lastRevisionAt || "",
    publicState: publicTrackerSnapshot(store.current),
  };
  if (payload.migrationRequired) {
    payload.level = "amber";
    payload.code = "migration_required";
    payload.text = "Legacy v1.3.1 state found. Open Continuity and choose Migrate Current Chat.";
  } else if (payload.processing) {
    payload.level = "amber";
    payload.code = "processing";
    payload.text = "Continuity Engine is updating scene and arc state…";
  } else if (payload.lastError) {
    payload.level = "amber";
    payload.code = "error";
    payload.text = `Continuity Engine kept the last valid state: ${payload.lastError}`;
  } else if (payload.lastWarning) {
    payload.level = "amber";
    payload.code = "recovered";
    payload.text = `Continuity Engine updated state conservatively: ${payload.lastWarning}`;
  } else if (caseError) {
    payload.level = "amber";
    payload.code = "invalid_profile";
    payload.text = `Continuity Engine could not save the private profile: ${caseError}`;
  } else if (base.level === "green" && caseMessageId && !profileSaved) {
    payload.level = "amber";
    payload.code = "profile_saving";
    payload.text = "Continuity Engine detected. Saving the private profile outside chat context…";
  } else if (base.level === "green" && caseMessageId && profileSaved) {
    payload.level = "green";
    payload.code = "ready";
    payload.text = "Continuity Engine active. Private profile saved; scene and arc tracking are automatic.";
  } else if (base.level === "green") {
    payload.code = "ready_no_profile";
    payload.text = "Continuity Engine ready. No Date Simulator v1.4.x or v1.5.x private profile was found in this chat yet.";
  }
  if (options.includePrivate) payload.state = store.current;
  return payload;
}

async function publishStatus(chatId, options = {}, userId) {
  sendFrontend(await statusPayload(chatId, options), userForChat(chatId, userId));
}

async function selectedBranchStillMatches(chatId, turn) {
  const messages = await spindle.chat.getMessages(chatId);
  const index = messages.findIndex((message) => String(message?.id ?? "") === String(turn.assistant.id));
  if (index < 0) return false;
  return prefixFingerprint(messages, index) === turn.fingerprint;
}

function resetForEpoch(store, context) {
  if (store.epochKey === context.epochKey) return store;
  const next = createStore(store.chatId);
  next.epochKey = context.epochKey;
  next.caseText = context.caseText ?? "";
  next.migrationRequired = context.migrationRequired;
  return next;
}

function recordRevision(store, timestamp = new Date().toISOString()) {
  store.revision += 1;
  store.lastRevisionAt = timestamp;
}

async function performMigration(chatId, messages, context, store, config, userId) {
  const turns = listEligibleTurns(messages, context);
  const latest = turns.at(-1);
  if (!latest) throw new Error("No immersive assistant turn is available to migrate.");
  const result = await runMigrationTracker(
    spindle,
    {
      caseText: context.caseText,
      legacySceneText: context.legacySceneText,
      transcript: transcriptForMigration(messages, context),
      sourceMessageId: String(latest.assistant.id),
    },
    config,
    userId,
  );
  if (!(await selectedBranchStillMatches(chatId, latest))) {
    throw new Error("The selected branch changed during migration.");
  }
  const createdAt = new Date().toISOString();
  store.checkpoints[latest.key] = {
    fingerprint: latest.fingerprint,
    state: result.state,
    warnings: result.warnings,
    createdAt,
    migrated: true,
  };
  store.current = result.state;
  store.lastWarning = result.warnings.join("; ").slice(0, 500);
  store.migrationAccepted = true;
  store.migrationRequired = false;
  store.migrationBaselineKey = latest.key;
  store.migrationBaselineFingerprint = latest.fingerprint;
  recordRevision(store, createdAt);
  return store;
}

async function reconcileChat(chatId, options = {}, userId) {
  if (!chatId || deletedChats.has(chatId) || !spindle.permissions.has("chat_mutation")) return;
  const scopedUserId = userForChat(chatId, userId);
  const config = await loadConfig();
  const messages = await spindle.chat.getMessages(chatId);
  const context = deriveTranscriptContext(messages);
  const existingStore = await spindle.storage.exists(storePath(chatId));
  if (!context.active && !existingStore) {
    await publishStatus(chatId, {}, scopedUserId);
    return;
  }
  let store = resetForEpoch(await loadStore(chatId), context);

  if (!context.active) {
    store.caseText = "";
    store.current = null;
    store.processing = false;
    store.migrationRequired = false;
    store.lastError = "";
    store.lastWarning = "";
    await saveStore(chatId, store);
    await mirrorStore(chatId, store, context);
    await publishStatus(chatId, {}, scopedUserId);
    return;
  }

  // Stable profile persistence is deterministic and must not wait for tracker
  // generation, provider availability, or structured-output repair.
  store.caseText = context.caseText;
  store.processing = false;
  await saveStore(chatId, store);
  await mirrorStore(chatId, store, context);
  await publishStatus(chatId, {}, scopedUserId);

  const nativeCurrent = /\b(?:Date Simulator\s+)?v1\.(?:4(?:\.\d+)?|5)\b/i.test(context.caseText);
  if (!nativeCurrent && !store.migrationAccepted && !options.allowMigration) {
    store.migrationRequired = true;
    store.processing = false;
    await saveStore(chatId, store);
    await mirrorStore(chatId, store, context);
    await publishStatus(chatId, {}, scopedUserId);
    return;
  }

  if (!nativeCurrent && store.migrationAccepted && store.migrationBaselineKey) {
    const turns = listEligibleTurns(messages, context);
    const baselineIndex = turns.findIndex(
      (turn) =>
        turn.key === store.migrationBaselineKey &&
        turn.fingerprint === store.migrationBaselineFingerprint,
    );
    const baseline = baselineIndex >= 0 ? selectCheckpoint(store, turns[baselineIndex]) : null;
    if (!baseline) {
      store.migrationAccepted = false;
      store.migrationRequired = true;
      store.migrationBaselineKey = "";
      store.migrationBaselineFingerprint = "";
      store.current = null;
      store.processing = false;
      await saveStore(chatId, store);
      await mirrorStore(chatId, store, context);
      await publishStatus(chatId, {}, scopedUserId);
      return;
    }
  }

  if (!config.enabled) {
    store.processing = false;
    await saveStore(chatId, store);
    await mirrorStore(chatId, store, context);
    await publishStatus(chatId, {}, scopedUserId);
    return;
  }
  if (!spindle.permissions.has("generation")) {
    store.processing = false;
    store.lastError = "Generation permission is not granted.";
    await saveStore(chatId, store);
    await mirrorStore(chatId, store, context);
    await publishStatus(chatId, {}, scopedUserId);
    return;
  }

  store.processing = true;
  store.lastError = "";
  await saveStore(chatId, store);
  await publishStatus(chatId, {}, scopedUserId);

  try {
    if (options.allowMigration && !nativeCurrent && !store.migrationAccepted) {
      store = await performMigration(chatId, messages, context, store, config, scopedUserId);
    } else {
      const turns = listEligibleTurns(messages, context);
      let previousState = null;
      let startIndex = 0;

      if (store.migrationAccepted && store.migrationBaselineKey) {
        const baselineIndex = turns.findIndex(
          (turn) =>
            turn.key === store.migrationBaselineKey &&
            turn.fingerprint === store.migrationBaselineFingerprint,
        );
        if (baselineIndex >= 0) {
          const baseline = selectCheckpoint(store, turns[baselineIndex]);
          if (baseline) {
            previousState = baseline.state;
            startIndex = baselineIndex + 1;
          }
        }
      }

      if (!previousState) {
        const prior = latestValidCheckpoint(store, turns);
        if (prior && prior.turnIndex === turns.length - 1 && !options.forceLatest) {
          previousState = prior.checkpoint.state;
          startIndex = turns.length;
        }
      }

      for (let index = startIndex; index < turns.length; index += 1) {
        const turn = turns[index];
        const existing = options.forceLatest && index === turns.length - 1
          ? null
          : selectCheckpoint(store, turn);
        if (existing) {
          previousState = existing.state;
          continue;
        }
        const result = await runTracker(
          spindle,
          {
            caseText: context.caseText,
            previousState,
            userText: turn.userText,
            assistantText: turn.assistantText,
            sourceMessageId: String(turn.assistant.id),
          },
          config,
          scopedUserId,
        );
        if (!(await selectedBranchStillMatches(chatId, turn))) {
          throw new Error("The selected branch changed while tracking.");
        }
        const createdAt = new Date().toISOString();
        store.checkpoints[turn.key] = {
          fingerprint: turn.fingerprint,
          state: result.state,
          warnings: result.warnings,
          createdAt,
        };
        previousState = result.state;
        store.lastWarning = result.warnings.join("; ").slice(0, 500);
        recordRevision(store, createdAt);
      }

      const liveKeys = new Set(turns.map((turn) => turn.key));
      store.checkpoints = Object.fromEntries(
        Object.entries(store.checkpoints).filter(([key]) => liveKeys.has(key)),
      );
      store.current = previousState;
    }
    store.lastError = "";
  } catch (error) {
    store.lastError = String(error?.message ?? error).slice(0, 500);
    spindle.log.warn(`Date Simulator continuity update failed for ${chatId}: ${store.lastError}`);
  } finally {
    store.processing = false;
    await saveStore(chatId, store);
    await mirrorStore(chatId, store, context);
    await publishStatus(chatId, {}, scopedUserId);
  }
}

function scheduleChatTask(chatId, task, label = "Continuity queue") {
  if (!chatId) return Promise.resolve();
  const previous = queues.get(chatId) ?? Promise.resolve();
  const current = previous
    .catch(() => undefined)
    .then(task)
    .catch((error) => spindle.log.error(`${label} failed: ${String(error)}`))
    .finally(() => {
      if (queues.get(chatId) === current) queues.delete(chatId);
    });
  queues.set(chatId, current);
  return current;
}

function scheduleReconcile(chatId, options = {}, userId) {
  if (!chatId || deletedChats.has(chatId)) return Promise.resolve();
  const scopedUserId = userForChat(chatId, userId);
  return scheduleChatTask(
    chatId,
    () => reconcileChat(chatId, options, scopedUserId),
    "Continuity queue",
  );
}

function normalizeForkEvent(payload) {
  const sourceChatId = typeof payload?.sourceChatId === "string" ? payload.sourceChatId.trim() : "";
  const forkedChatId = typeof payload?.forkedChatId === "string" ? payload.forkedChatId.trim() : "";
  const forkedAtMessageId = typeof payload?.forkedAtMessageId === "string"
    ? payload.forkedAtMessageId.trim()
    : "";
  const rawMap = payload?.messageIdMap;
  if (!sourceChatId || !forkedChatId || sourceChatId === forkedChatId || !forkedAtMessageId) return null;
  if (!rawMap || typeof rawMap !== "object" || Array.isArray(rawMap)) return null;

  const messageIdMap = new Map();
  const forkedIds = new Set();
  for (const [sourceId, forkedIdValue] of Object.entries(rawMap)) {
    const forkedId = typeof forkedIdValue === "string" ? forkedIdValue.trim() : "";
    if (!sourceId || !forkedId || forkedIds.has(forkedId)) return null;
    messageIdMap.set(sourceId, forkedId);
    forkedIds.add(forkedId);
  }
  if (!messageIdMap.has(forkedAtMessageId)) return null;
  return { sourceChatId, forkedChatId, forkedAtMessageId, messageIdMap };
}

/** Seed a newly-created Lumiverse fork from the source chat's validated prefix. */
async function inheritForkCheckpoints(payload, userId) {
  const fork = normalizeForkEvent(payload);
  if (!fork || !spindle.permissions.has("chat_mutation")) return false;
  const scopedUserId = userForChat(fork.forkedChatId, userId);
  const forkPath = storePath(fork.forkedChatId);
  if (await spindle.storage.exists(forkPath)) {
    const existing = await loadStore(fork.forkedChatId);
    if (!isInertStore(existing)) return false;
  }

  const forkMessages = await spindle.chat.getMessages(fork.forkedChatId);
  const reverseMap = new Map([...fork.messageIdMap].map(([sourceId, forkedId]) => [forkedId, sourceId]));
  if (
    forkMessages.length !== fork.messageIdMap.size
    || forkMessages.some((message) => !reverseMap.has(String(message?.id ?? "")))
  ) {
    spindle.log.warn(`Continuity fork inheritance skipped for ${fork.forkedChatId}: incomplete message id map.`);
    return false;
  }

  // Reconstruct the exact source prefix from the copied branch. This avoids a
  // race with later edits or messages in the source chat while still allowing
  // its stored fingerprints to prove that every inherited checkpoint matches.
  const sourcePrefix = forkMessages.map((message) => ({
    ...message,
    id: reverseMap.get(String(message.id)),
  }));
  const sourceContext = deriveTranscriptContext(sourcePrefix);
  const forkContext = deriveTranscriptContext(forkMessages);
  if (
    sourceContext.active !== forkContext.active
    || String(sourceContext.caseText ?? "") !== String(forkContext.caseText ?? "")
  ) {
    spindle.log.warn(`Continuity fork inheritance skipped for ${fork.forkedChatId}: branch context mismatch.`);
    return false;
  }
  if (!forkContext.active) return true;

  const sourceStore = await loadStore(fork.sourceChatId);
  const sourceTurns = listEligibleTurns(sourcePrefix, sourceContext);
  const forkTurns = listEligibleTurns(forkMessages, forkContext);
  if (sourceTurns.length !== forkTurns.length) {
    spindle.log.warn(`Continuity fork inheritance skipped for ${fork.forkedChatId}: eligible turn mismatch.`);
    return false;
  }

  const inherited = createStore(fork.forkedChatId);
  inherited.epochKey = forkContext.epochKey;
  inherited.caseText = forkContext.caseText ?? "";
  let latestCheckpoint = null;
  let inheritedMigrationBaseline = false;

  for (let index = 0; index < sourceTurns.length; index += 1) {
    const sourceTurn = sourceTurns[index];
    const forkTurn = forkTurns[index];
    if (fork.messageIdMap.get(String(sourceTurn.assistant.id)) !== String(forkTurn.assistant.id)) break;
    const checkpoint = selectCheckpoint(sourceStore, sourceTurn);
    if (!checkpoint) break;
    const state = remapTrackerStateSourceIds(checkpoint.state, fork.messageIdMap);
    if (!state) {
      spindle.log.warn(`Continuity fork inheritance stopped for ${fork.forkedChatId}: incomplete provenance map.`);
      break;
    }
    const forkCheckpoint = {
      ...checkpoint,
      fingerprint: forkTurn.fingerprint,
      state,
    };
    inherited.checkpoints[forkTurn.key] = forkCheckpoint;
    inherited.current = state;
    inherited.revision += 1;
    inherited.lastRevisionAt = checkpoint.createdAt || inherited.lastRevisionAt;
    inherited.lastWarning = Array.isArray(checkpoint.warnings)
      ? checkpoint.warnings.join("; ").slice(0, 500)
      : "";
    latestCheckpoint = forkCheckpoint;

    if (
      sourceStore.migrationAccepted
      && sourceStore.migrationBaselineKey === sourceTurn.key
      && sourceStore.migrationBaselineFingerprint === sourceTurn.fingerprint
    ) {
      inherited.migrationAccepted = true;
      inherited.migrationRequired = false;
      inherited.migrationBaselineKey = forkTurn.key;
      inherited.migrationBaselineFingerprint = forkTurn.fingerprint;
      inheritedMigrationBaseline = true;
    }
  }

  if (!inheritedMigrationBaseline) {
    inherited.migrationAccepted = false;
    inherited.migrationRequired = forkContext.migrationRequired;
  }
  inherited.processing = false;
  inherited.lastError = "";
  if (!latestCheckpoint) inherited.lastRevisionAt = "";

  await saveStore(fork.forkedChatId, inherited);
  await mirrorStore(fork.forkedChatId, inherited, forkContext);
  await publishStatus(fork.forkedChatId, {}, scopedUserId);
  return true;
}

function scheduleForkInheritance(payload, userId) {
  const fork = normalizeForkEvent(payload);
  if (!fork) return Promise.resolve(false);
  const sourcePending = queues.get(fork.sourceChatId) ?? Promise.resolve();
  // Reserve the fork queue immediately. CHAT_SWITCHED can follow the fork
  // event very quickly, and its normal reconciliation must run after seeding.
  return scheduleChatTask(
    fork.forkedChatId,
    async () => {
      await sourcePending.catch(() => undefined);
      return inheritForkCheckpoints(payload, userId);
    },
    "Continuity fork inheritance",
  );
}

async function removeDeletedChatStore(chatId) {
  if (!chatId) return;
  deletedChats.add(chatId);
  forgetChat(chatId);
  await scheduleChatTask(
    chatId,
    async () => {
      await spindle.storage.delete(storePath(chatId));
      forgetChat(chatId);
    },
    "Continuity chat cleanup",
  );
}

async function deleteUnusedStores() {
  const scan = await scanUnusedStores();
  let deleted = 0;
  let skipped = 0;
  let failed = 0;
  let deletedBytes = 0;

  for (const candidate of scan.candidates) {
    let removed = false;
    await scheduleChatTask(candidate.chatId, async () => {
      try {
        const current = await readCleanupStore(candidate.path.slice("chats/".length));
        if (!current) {
          skipped += 1;
          return;
        }
        const stillUnused = candidate.reason === "inert"
          ? isInertStore(current.value)
          : await missingChat(current.chatId);
        if (!stillUnused) {
          skipped += 1;
          return;
        }
        if (candidate.reason === "orphan") {
          deletedChats.add(candidate.chatId);
          forgetChat(candidate.chatId);
        }
        await spindle.storage.delete(candidate.path);
        removed = true;
      } catch (error) {
        failed += 1;
        spindle.log.warn(`Continuity cleanup could not delete ${candidate.path}: ${String(error?.message ?? error)}`);
      }
    }, "Continuity storage cleanup");
    if (removed) {
      deleted += 1;
      deletedBytes += candidate.sizeBytes;
    }
  }

  return { ...scan, deleted, skippedDuringDelete: skipped, failed, deletedBytes };
}

async function reconcileBeforePrompt(chatId) {
  if (!chatId || !spindle.permissions.has("chat_mutation")) return false;
  // Queue one verification pass even when an event-triggered update is already
  // running. The follow-up pass is normally a zero-generation checkpoint hit,
  // and closes races where prompt interception beats the message event.
  await scheduleReconcile(chatId, {}, userForChat(chatId));
  return true;
}

async function interceptPrompt(messages, context) {
  if (!isV14Prompt(messages)) return messages;
  const config = await loadConfig();
  if (!config.enabled) return messages;
  const chatId = context?.chatId;
  if (chatId) await reconcileBeforePrompt(chatId);

  let caseText = "";
  let state = null;
  let status = "starting";
  if (chatId) {
    const store = await loadStore(chatId);
    caseText = store.caseText;
    state = store.current;
    status = store.migrationRequired
      ? "migration_required"
      : store.lastError
        ? "degraded"
        : store.processing
          ? "processing"
          : "active";
  }

  // Setup turns need the card's worked case examples and gain nothing from an
  // empty tracker block. A Surprise Me turn may receive one deterministic,
  // prompt-only casting draw; begin continuity compaction only after a live
  // profile is saved.
  if (!caseText) {
    const sample = buildSurpriseMeSample(messages, chatId);
    if (!sample) return stripStartupMenuMarkers(messages);
    const sampledMessages = [...sample.messages];
    sampledMessages.splice(sample.insertionIndex, 0, sample.message);
    return {
      messages: sampledMessages,
      breakdown: [{ messageIndex: sample.insertionIndex, name: "Date Simulator Case Sampler" }],
    };
  }

  const compacted = compactPromptMessages(messages, caseText, state, status);
  return {
    messages: compacted.messages,
    breakdown: [
      {
        messageIndex: compacted.injectionIndex,
        name: "Date Simulator Continuity Engine",
      },
    ],
  };
}

function tryRegisterInterceptor() {
  if (interceptorRegistered || !spindle.permissions.has("interceptor")) return;
  spindle.registerInterceptor(interceptPrompt, 250);
  interceptorRegistered = true;
  spindle.log.info("Date Simulator Continuity Engine interceptor registered.");
}

for (const eventName of [
  "MESSAGE_SENT",
  "MESSAGE_EDITED",
  "MESSAGE_DELETED",
  "MESSAGE_SWIPED",
  "SWIPE_EDITED",
]) {
  spindle.on(eventName, (payload, userId) => {
    const chatId = adoptActiveChat(payload?.chatId, userId);
    return scheduleReconcile(chatId, {}, userId);
  });
}

spindle.on("CHAT_FORKED", (payload, userId) => scheduleForkInheritance(payload, userId));

spindle.on("CHAT_DELETED", (payload) => {
  const chatId = typeof payload?.id === "string" ? payload.id : "";
  return removeDeletedChatStore(chatId);
});

spindle.on("CHAT_SWITCHED", (payload, userId) => {
  if (typeof payload?.chatId === "string" && payload.chatId) {
    const chatId = adoptActiveChat(payload.chatId, userId);
    scheduleReconcile(chatId, {}, userId);
    return;
  }
  if (validUserId(userId)) {
    const previousChatId = activeChatByUser.get(userId);
    activeChatByUser.delete(userId);
    if (activeChatId === previousChatId) activeChatId = null;
  } else {
    activeChatId = null;
  }
  publishStatus(null, {}, userId);
});

spindle.permissions.onChanged(({ permission, granted }) => {
  if (permission === "interceptor" && granted) tryRegisterInterceptor();
  if (activeChatId) scheduleReconcile(activeChatId);
});

spindle.onFrontendMessage(async (payload, userId) => {
  frontendUserId = userId;
  const type = payload?.type;
  if (type === "continuity_get_status") {
    const chatId = adoptActiveChat(payload.chatId, userId);
    if (chatId) scheduleReconcile(chatId, {}, userId);
    sendFrontend(await statusPayload(chatId, { includePrivate: Boolean(payload.includePrivate) }), userId);
  } else if (type === "continuity_get_connections") {
    let connections = [];
    let error = "";
    const permissionGranted = spindle.permissions.has("generation");
    if (permissionGranted) {
      try {
        const listed = await spindle.connections.list(userId);
        connections = Array.isArray(listed) ? listed : [];
      } catch (listError) {
        connections = [];
        error = listError instanceof Error ? listError.message : String(listError);
      }
    }
    sendFrontend({
      type: "continuity_connections",
      connections,
      permissionGranted,
      error,
    }, userId);
  } else if (type === "continuity_save_config") {
    const config = await saveConfig(payload.config);
    sendFrontend({ type: "continuity_config_saved", config }, userId);
    const chatId = adoptActiveChat(payload.chatId, userId);
    if (chatId) scheduleReconcile(chatId, {}, userId);
  } else if (
    type === "continuity_set_widget_visibility"
    && typeof payload.showStatusWidget === "boolean"
  ) {
    const config = await saveWidgetVisibility(payload.showStatusWidget);
    sendFrontend({ type: "continuity_config_saved", config }, userId);
    const chatId = adoptActiveChat(payload.chatId, userId);
    if (chatId) publishStatus(chatId, {}, userId);
  } else if (type === "continuity_scan_cleanup") {
    sendFrontend({
      type: "continuity_action_started",
      action: "cleanup_scan",
      message: "Scanning extension-owned tracking files…",
    }, userId);
    try {
      const scan = await scanUnusedStores();
      const count = scan.candidates.length;
      const token = count > 0 ? crypto.randomUUID() : "";
      const key = cleanupUserKey(userId);
      if (token) {
        pendingCleanupByUser.set(key, {
          token,
          expiresAt: Date.now() + CLEANUP_CONFIRMATION_TTL_MS,
        });
      } else {
        pendingCleanupByUser.delete(key);
      }
      sendFrontend({
        type: "continuity_cleanup_scan_result",
        ok: scan.errors === 0,
        token,
        count,
        inert: scan.inert,
        orphan: scan.orphan,
        sizeBytes: scan.sizeBytes,
        skipped: scan.skipped,
        errors: scan.errors,
        message: count > 0
          ? `Found ${count} unused tracking file${count === 1 ? "" : "s"} (${formatStorageSize(scan.sizeBytes)}): ${scan.orphan} orphaned, ${scan.inert} inert.${scan.errors > 0 ? ` ${scan.errors} other file${scan.errors === 1 ? " could" : "s could"} not be verified and will remain untouched.` : ""} Click Delete to confirm.`
          : scan.errors > 0
            ? `No confirmed unused files were found; ${scan.errors} file${scan.errors === 1 ? "" : "s"} could not be verified and were left untouched.`
            : "No unused tracking files were found.",
      }, userId);
    } catch (error) {
      pendingCleanupByUser.delete(cleanupUserKey(userId));
      sendFrontend({
        type: "continuity_cleanup_scan_result",
        ok: false,
        token: "",
        count: 0,
        message: `Cleanup scan failed without deleting anything: ${String(error?.message ?? error)}`,
      }, userId);
    }
  } else if (type === "continuity_cleanup_unused") {
    const key = cleanupUserKey(userId);
    const pending = pendingCleanupByUser.get(key);
    pendingCleanupByUser.delete(key);
    if (
      !pending
      || typeof payload.token !== "string"
      || payload.token !== pending.token
      || Date.now() > pending.expiresAt
    ) {
      sendFrontend({
        type: "continuity_action_result",
        action: "cleanup",
        ok: false,
        message: "Cleanup confirmation expired. Scan again before deleting files.",
      }, userId);
      return;
    }
    sendFrontend({
      type: "continuity_action_started",
      action: "cleanup",
      message: "Rechecking and deleting confirmed unused tracking files…",
    }, userId);
    try {
      const result = await deleteUnusedStores();
      const ok = result.failed === 0;
      const suffix = result.skippedDuringDelete > 0
        ? ` ${result.skippedDuringDelete} changed file${result.skippedDuringDelete === 1 ? " was" : "s were"} left untouched.`
        : "";
      sendFrontend({
        type: "continuity_action_result",
        action: "cleanup",
        ok,
        message: result.deleted > 0
          ? `Deleted ${result.deleted} unused tracking file${result.deleted === 1 ? "" : "s"} (${formatStorageSize(result.deletedBytes)}).${suffix}`
          : result.failed > 0
            ? `No files were deleted; ${result.failed} deletion${result.failed === 1 ? "" : "s"} failed.${suffix}`
            : `No files were deleted after the safety recheck.${suffix}`,
      }, userId);
    } catch (error) {
      sendFrontend({
        type: "continuity_action_result",
        action: "cleanup",
        ok: false,
        message: `Cleanup failed: ${String(error?.message ?? error)}`,
      }, userId);
    }
  } else if (type === "continuity_reprocess") {
    const chatId = adoptActiveChat(payload.chatId, userId);
    if (!chatId) {
      sendFrontend({
        type: "continuity_action_result",
        action: "reprocess",
        ok: false,
        message: "Open a Date Simulator chat before reprocessing.",
      }, userId);
      return;
    }
    sendFrontend({
      type: "continuity_action_started",
      action: "reprocess",
      chatId,
      message: "Reprocessing the latest eligible immersive turn…",
    }, userId);
    await scheduleReconcile(chatId, { forceLatest: true }, userId);
    const status = await statusPayload(chatId, { includePrivate: Boolean(payload.includePrivate) });
    const ok = !status.lastError && !status.migrationRequired;
    sendFrontend({
      type: "continuity_action_result",
      action: "reprocess",
      chatId,
      ok,
      message: ok
        ? status.lastWarning
          ? `Reprocess complete at revision ${status.revision || 0} with conservative recovery: ${status.lastWarning}`
          : `Reprocess complete at revision ${status.revision || 0}.`
        : status.lastError
          ? `Reprocess finished with a tracker error: ${status.lastError}`
          : "Reprocess cannot continue until this chat is migrated.",
      status,
    }, userId);
  } else if (type === "continuity_migrate") {
    const chatId = adoptActiveChat(payload.chatId, userId);
    if (!chatId) {
      sendFrontend({
        type: "continuity_action_result",
        action: "migrate",
        ok: false,
        message: "Open a Date Simulator chat before migrating.",
      }, userId);
      return;
    }
    sendFrontend({
      type: "continuity_action_started",
      action: "migrate",
      chatId,
      message: "Migrating the current chat…",
    }, userId);
    await scheduleReconcile(chatId, { allowMigration: true }, userId);
    const status = await statusPayload(chatId, { includePrivate: Boolean(payload.includePrivate) });
    const ok = !status.lastError && !status.migrationRequired;
    sendFrontend({
      type: "continuity_action_result",
      action: "migrate",
      chatId,
      ok,
      message: ok
        ? `Migration complete at revision ${status.revision || 0}.`
        : status.lastError
          ? `Migration finished with an error: ${status.lastError}`
          : "Migration is still required.",
      status,
    }, userId);
  }
});

tryRegisterInterceptor();
spindle.log.info("Date Simulator Continuity Engine loaded.");

const backendTest = Object.freeze({
  normalizeConfig,
  publicTrackerSnapshot,
  readiness,
  safeChatToken,
  isInertStore,
  adoptActiveChat,
  userForChat,
  normalizeForkEvent,
  inheritForkCheckpoints,
});
